            while (true) {
                _ = service_fn(ctx);
                _ = s.drained_mutex.lock();
                if (((!s.loopOf(.regular).concurrent_tasks.isEmpty()) or (!s.loopOf(.macro).concurrent_tasks.isEmpty()))) {
                    _ = s.drained_mutex.unlock();
                    continue;
                }
                if ((s.tickets.load(.seq_cst) == 0)) {
                    _ = s.hot.state.store(@intFromEnum(State.closed), .seq_cst);
                    _ = s.drained_mutex.unlock();
                    break;
                }
                _ = (blk_catch_0: { break :blk_catch_0 ((s.drained_cond.timedWait((&s.drained_mutex), std.time.ns_per_s)) catch |__ce_0| { _ = &__ce_0;  }); });
                _ = s.drained_mutex.unlock();
            }
            if ((s.active.load(.seq_cst) != 0)) {
                _ = s.drained_mutex.lock();
                while ((s.active.load(.seq_cst) != 0)) {
                    _ = s.drained_cond.wait((&s.drained_mutex));
                }
                _ = s.drained_mutex.unlock();
            }
            _ = service_fn(ctx);
    }

