pub const ConcurrentPoster = union(enum) {
    js: Ticket,
    mini: *MiniEventLoop,

pub fn fromEventLoopHandle(h: EventLoopHandle) ConcurrentPoster {
            return (switch (h) {
.js => |js_loop| .{ .js = js_loop.virtual_machine.ticket() },
.mini => |mini_loop| .{ .mini = mini_loop },
});
    }

pub fn isJs(self: ConcurrentPoster) bool {
            return (self == .js);
    }

pub fn clone(self: ConcurrentPoster) ConcurrentPoster {
            return (switch (self) {
.js => |t| .{ .js = t.clone() },
.mini => |m| .{ .mini = m },
});
    }

pub fn deinit(self: *ConcurrentPoster) void {
            switch (self.*) {
.js => |*t| {
_ = t.deinit();
},
.mini => {

},
}
    }

pub fn postJs(self: ConcurrentPoster, task: *ConcurrentTask) void {
            switch (self) {
.js => |t| {
_ = t.post(task);
},
.mini => {
_ = bun.debugAssert(false);
},
}
    }

pub fn postMini(self: ConcurrentPoster, task: *AnyTaskWithExtraContext) void {
            switch (self) {
.mini => |m| {
_ = m.enqueueTaskConcurrent(task);
},
.js => {
_ = bun.debugAssert(false);
},
}
    }
};

pub const IsolatedPosterInner = struct {
    ref_count: RefCount,
    open: std.atomic.Value(bool) = std.atomic.Value(bool).init(true),
    active: std.atomic.Value(u32) = std.atomic.Value(u32).init(0),
    event_loop: *EventLoop,

pub fn destroy(inner: *IsolatedPosterInner) void {
            _ = bun.destroy(inner);
    }

pub fn init(event_loop: *EventLoop) *IsolatedPosterInner {
            return bun.new(IsolatedPosterInner, .{ .ref_count = .init(), .event_loop = event_loop });
    }

pub fn close(self: IsolatedPosterInner) void {
            _ = self.open.store(false, .seq_cst);
            while ((self.active.load(.seq_cst) != 0)) {
                _ = std.atomic.spinLoopHint();
            }
    }

pub fn post(self: IsolatedPosterInner, task: *ConcurrentTask) Posted {
            _ = self.active.fetchAdd(1, .seq_cst);
            const is_open = self.open.load(.seq_cst);
            if (is_open) {
                _ = self.event_loop.concurrent_tasks.push(task);
                _ = self.event_loop.wakeup();
            }
            _ = self.active.fetchSub(1, .seq_cst);
            if (is_open) {
                return .queued;
            }
            return .{ .refused = task };
    }
    const RefCount = bun.ptr.ThreadSafeRefCount(IsolatedPosterInner, "ref_count", IsolatedPosterInner.destroy, .{});
    const ref = RefCount.ref;
    const deref = RefCount.deref;
};

const Environment = bun.Environment;
const Output = bun.Output;
const jsc = bun.jsc;
const VirtualMachine = jsc.VirtualMachine;
const EventLoop = jsc.EventLoop;
const ConcurrentTask = jsc.ConcurrentTask;
const MiniEventLoop = jsc.MiniEventLoop;
const EventLoopHandle = jsc.EventLoopHandle;
const AnyTaskWithExtraContext = jsc.AnyTaskWithExtraContext;

extern "c" fn Bun__deleteEventLoopTask(task: *jsc.CppTask) callconv(.c) void;

pub fn testGateArmed(s: *Shared) bool {
        if (comptime Environment.isDebug) {
            return (s.debug.gate.load(.monotonic) and (std.Thread.getCurrentId() != s.debug.js_thread));
        }
        return false;
}

pub fn testGateParkUntilDraining(s: *Shared) void {
        _ = s.drained_mutex.lock();
        defer {
        _ = s.drained_mutex.unlock();
        }
        while ((@intFromEnum(s.getState()) < @intFromEnum(State.draining))) {
            _ = s.drained_cond.wait((&s.drained_mutex));
        }
}

pub fn testGateBeforeTicketPost(s: *Shared) void {
        if (comptime Environment.isDebug) {
            if (testGateArmed(s)) {
                _ = testGateParkUntilDraining(s);
            }
        }
}

pub export fn Bun__VmHandle__retain(vm: *VirtualMachine) callconv(.c) *const Shared {
        return vm.vmHandle().intoRef();
}

pub export fn Bun__VmHandle__retainRef(r: *const Shared) callconv(.c) *const Shared {
        const h = VmHandle.fromRef(r);
        return h.clone().intoRef();
}

pub export fn Bun__VmHandle__release(r: *const Shared) callconv(.c) void {
        var h = VmHandle.fromRef(r);
        _ = &h;
        _ = h.deinit();
}

pub export fn Bun__VmHandle__postAndRelease(r: *const Shared, task: *jsc.CppTask) callconv(.c) void {
        var h = VmHandle.fromRef(r);
        _ = &h;
        defer {
        _ = h.deinit();
        }
        _ = h.postCppTask(task);
}

pub export fn Bun__eventLoop__refKeepAlive(vm: *VirtualMachine, delta: c_int) callconv(.c) void {
        if ((delta > 0)) {
            _ = vm.eventLoop().refConcurrently();
        } else {
            _ = vm.eventLoop().unrefConcurrently();
        }
}

pub export fn Bun__VmHandle__refKeepAlive(r: *const Shared, delta: c_int) callconv(.c) void {
        const h = VmHandle.fromRef(r);
        const sign: i32 = (if ((delta > 0)) 1 else (if ((delta < 0)) -1 else 0));
        _ = h.addKeepAlive(.regular, sign);
}

pub export fn Bun__VmHandle__scriptAllowed(r: *const Shared) callconv(.c) bool {
        const h = VmHandle.fromRef(r);
        return h.scriptAllowed();
}

pub export fn Bun__VmHandle__stateAddress(r: *const Shared) callconv(.c) *const std.atomic.Value(u8) {
        return (&r.hot.state);
}
